import React from 'react';

export default function Newsletter() {
  return (
    <div className="py-5 text-white" style={{ background: 'linear-gradient(135deg, #0d6efd, #0a58ca)' }}>
      <div className="container text-center">
        <h2 className="fw-bold mb-3">📬 اشترك في نشرتنا العقارية</h2>
        <p className="mb-4 opacity-75">احصل على أحدث العروض والفرص الاستثمارية مباشرة في بريدك الوارد.</p>
        <div className="row justify-content-center">
          <div className="col-md-6">
            <div className="input-group mb-3">
              <input type="email" className="form-control form-control-lg border-0" placeholder="أدخل بريدك الإلكتروني" aria-label="Email" />
              <button className="btn btn-dark btn-lg px-4" type="button" onClick={() => alert('شكراً لاشتراكك! 📩')}>اشترك الآن</button>
            </div>
            <small className="opacity-50">نعدك بعدم إرسال رسائل مزعجة.</small>
          </div>
        </div>
      </div>
    </div>
  );
}
